mapper.select:
SELECT pmid FROM openlb_pmid_task
WHERE status='PENDING' AND (next_retry_time IS NULL OR next_retry_time<=NOW())
ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE openlb_pmid_task
SET status='SUCCESS',attempt_count=attempt_count+1,last_error=NULL,next_retry_time=NULL,completed_time=NOW(),update_time=NOW()
WHERE pmid IN #{pmid}

UPDATE openlb_pmid_task
SET status='EMPTY',attempt_count=attempt_count+1,last_error=NULL,next_retry_time=NULL,completed_time=NOW(),update_time=NOW()
WHERE pmid IN #{pmid}
